{
  "missionStatement": "Study room-temperature superconducting materials via online research and synthesize a comprehensive chemistry and physics framework for discovering and manufacturing new compounds.",
  "criteria": [
    {
      "description": "Online research summary document is updated with findings from at least 5 recent (2020+) peer-reviewed papers on room-temperature superconductivity, including key data on Tc, pressure, and material classes.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Proposed chemistry and physics document includes a theoretical model explaining the mechanism of room-temperature superconductivity in candidate materials, referencing BCS theory, electron-phonon coupling, and any novel mechanisms.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Candidate materials document is updated with at least three new candidate compounds identified from literature, including predicted Tc, crystal structure, and synthesis routes.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document includes detailed protocols for manufacturing at least two of the new candidate compounds, covering precursor preparation, high-pressure or thin-film techniques, and post-processing.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document is updated with methods to verify room-temperature superconductivity in the new candidates, including resistivity, magnetic susceptibility, and specific heat measurements.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Discovery strategy document outlines a systematic approach combining computational screening (e.g., DFT, machine learning) and experimental validation for identifying new room-temperature superconductors.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Roadmap document is updated with milestones for the next 6 months, including synthesis and characterization of top candidates, and integration of feedback from experimental results.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Manufacturing scalability document is updated with a section on challenges and potential solutions for scaling up synthesis of room-temperature superconducting compounds.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Novel mechanism document is updated with a description of any unconventional pairing mechanisms (e.g., excitonic, plasmonic) that could enable room-temperature superconductivity at ambient pressure.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Literature review document is updated with a summary of key experimental breakthroughs since 2020, including hydrides, nickelates, and carbon-based superconductors.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "All unit tests in the tests/ directory pass after any script modifications.",
      "expectedFiles": []
    },
    {
      "description": "The proposed chemistry and physics document includes a section on manufacturing scalability and challenges, referencing the manufacturing scalability document.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    }
  ]
}

{
  "missionStatement": "Incorporate online research findings on room-temperature superconductivity to enhance the proposed chemistry and physics, update candidate materials, synthesis methods, characterization techniques, and experimental protocols, and produce a comprehensive online research summary.",
  "criteria": [
    {
      "description": "Online research summary is updated with at least 5 recent papers (2020+) on room-temperature superconductivity, including key findings on hydride, nickelate, and carbon-based systems.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Proposed chemistry and physics document is revised to incorporate new mechanisms such as hydrogen-dominant metallic alloys, nickelate superconductors, and carbon-based superconductors, with references to online research.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Candidate materials list is updated with new compounds and their predicted critical temperatures, sourced from online research.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document is updated with new protocols for high-pressure synthesis, thin-film deposition, and doping techniques.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document is updated with new methods for measuring Tc, critical current, and magnetic susceptibility.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Discovery strategy document is updated with a systematic screening approach using machine learning and high-throughput computation.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Manufacturing scalability document is updated with considerations for large-scale production of room-temperature superconductors.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Roadmap is updated with new milestones for experimental validation and scaling of room-temperature superconductors.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Experimental protocols for hydride, nickelate, and carbon systems are updated based on online research findings.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md", "docs/experimental_protocol_nickelate.md", "docs/experimental_protocol_carbon.md"]
    },
    {
      "description": "Theoretical framework document is updated to incorporate new models such as BCS theory extensions, Eliashberg theory, and unconventional pairing mechanisms.",
      "expectedFiles": ["theoretical_framework.md"]
    }
  ]
}

{
