    {
      "description": "theoretical_framework.md is updated to incorporate the latest theoretical models from online research, including density functional theory predictions and machine learning approaches.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "discovery_strategy.md is updated to outline a systematic approach for screening and discovering new room-temperature superconductors, including high-throughput computational screening and experimental validation.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "roadmap.md is updated with new milestones and timelines based on the research findings, including short-term and long-term goals for synthesis and characterization.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "docs/novel_mechanism.md is updated to describe any novel superconducting mechanism identified during research (e.g., excitonic, plasmonic, or other).",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "docs/manufacturing_scalability.md is updated to discuss challenges and potential solutions for scaling up synthesis of room-temperature superconductors.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "docs/experimental_feedback_loop.md is updated to incorporate new experimental protocols and data analysis methods from online research.",
      "expectedFiles": ["docs/experimental_feedback_loop.md"]
    },
    {
      "description": "All updated documents are internally consistent and cross-reference each other appropriately.",
      "expectedFiles": []
    },
    {
      "description": "The existing test suite (tests/test_predict_tc.py, tests/test_query_database.py) passes after any script updates.",
      "expectedFiles": []
    },
    {
      "description": "docs/experimental_protocol_hydride.md is updated with the latest high-pressure synthesis and characterization protocols for hydride superconductors.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "docs/experimental_protocol_nickelate.md is updated with protocols for nickelate superconductors.",
      "expectedFiles": ["docs/experimental_protocol_nickelate.md"]
    },
    {
      "description": "docs/experimental_protocol_carbon.md is updated with protocols for carbon-based superconductors.",
      "expectedFiles": ["docs/experimental_protocol_carbon.md"]
    },
    {
      "description": "data/superconductor_database.json is updated with new candidate materials and their properties from online research.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "scripts/predict_tc.py is updated to incorporate new theoretical models or machine learning models for predicting Tc of candidate materials.",
      "expectedFiles": ["scripts/predict_tc.py"]
    }
  ]
}

